package com.finsightai.security;
import com.finsightai.model.AppUser; import com.finsightai.repository.AppUserRepository; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import java.util.List;
@Service public class CustomUserDetailsService implements UserDetailsService { private final AppUserRepository repo; public CustomUserDetailsService(AppUserRepository repo){this.repo=repo;} public UserDetails loadUserByUsername(String username){AppUser u=repo.findByUsername(username).orElseThrow(()->new UsernameNotFoundException(username)); return User.withUsername(u.getUsername()).password(u.getPassword()).authorities(List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole()))).disabled(!u.isEnabled()).build();}}
